node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createRouter } from './src/index.mjs';

const defaults = { enabled: true, timeout: 10, label: 'default', headers: { keep: 'yes', remove: 'old' } };
const broad = { id: 'broad', pattern: '/app/*', settings: { target: 'broad', enabled: false, timeout: 0, label: '' } };
const deeper = { id: 'deeper', pattern: '/app/admin/*', settings: { target: 'deeper' } };
const routes = [
  broad,
  { id: 'first-tie', pattern: '/tie/*', settings: { target: 'first' } },
  { id: 'second-tie', pattern: '/tie/*', settings: { target: 'second' } },
  { id: 'all', pattern: '*', settings: { target: 'all' } },
  { id: 'exact', pattern: '/app', settings: { target: 'exact' } },
  deeper,
];
const router = createRouter({ defaults, routes });
defaults.headers.keep = 'mutated';
broad.settings.target = 'mutated';
assert.equal(router.resolve('red', '/app').target, 'exact');
assert.equal(router.resolve('red', '/app/admin').target, 'deeper');
assert.equal(router.resolve('red', '/app/admin/x').enabled, false);
assert.equal(router.resolve('red', '/apple').target, 'all');
assert.equal(router.resolve('red', '/tie/x').target, 'first');
const first = router.resolve('red', '/app/admin/x');
assert.equal(first.timeout, 0);
assert.equal(first.label, '');
assert.equal(first.headers.keep, 'yes');
first.headers.keep = 'changed';
router.setTenant('red', { headers: { remove: null, custom: '', keep: 'tenant' } });
const updated = router.resolve('red', '/app/admin/x');
assert.equal(updated.headers.keep, 'tenant');
assert.equal(updated.headers.remove, undefined);
assert.equal(updated.headers.custom, '');
assert.equal(router.resolve('blue', '/app/admin/x').headers.keep, 'yes');
const overrides = { target: 'one' };
router.setTenant('green', overrides);
overrides.target = 'outside';
assert.equal(router.resolve('green', '/app/admin/x').target, 'one');
router.setTenant('green', { target: 'two' });
assert.equal(router.resolve('green', '/app/admin/x').target, 'two');
assert.equal(router.resolve('red', '/not-found'), null);
console.log('layered-routing assertions passed');
NODE

